begin;

create temporary table dambulla_editorial as select * from jsonb_to_recordset($content$[
{"slug":"dambulla-hot-air-balloon-rides-offering-sunrise-aerial-views-of-sigiriya-rock-and","name":"Cultural Triangle Sunrise Balloon Flight","category":"Adventure","short":"Rise with the first light above Dambulla's dry-zone landscape on a licensed seasonal balloon flight shaped entirely by wind and aviation conditions.","story":"Before sunrise, the balloon is prepared in the Dambulla–Kandalama area while the pilot studies the morning wind. Once airborne, roads and reservoirs become lines of light below, with forest, farmland and isolated rock outcrops revealing the scale of the Cultural Triangle. Sigiriya may be visible when route, haze and wind align, but no landmark or flight path can be guaranteed.\n\nBallooning is a seasonal aviation experience, not a fixed sightseeing circuit. The licensed operator and pilot control launch site, direction, duration and cancellation. Roam Ceylon confirms the operator, transfers and contingency arrangements so an unsafe morning is never pressured into operating.","duration":"Approximately 3–4 hours including preparation, flight and recovery; airborne time varies","season":"Seasonal — generally November to April, subject to safe dawn wind and visibility","highlights":["Pre-dawn inflation and a sunrise ascent","Aerial views across reservoirs, forest and cultivated dry-zone country","A silent wind-led journey rather than a fixed flight path","Perspective on the wider Cultural Triangle landscape","A licensed pilot's real-time assessment of weather and landing conditions"],"unique":["The route is created by the morning wind and is different on every flight","The landscape is understood at regional scale rather than as isolated monuments","Safety-led cancellation is an essential part of a credible balloon product","Sigiriya is a possible view, never a guaranteed flyover"],"included":["Licensed commercial balloon operator and pilot","Pre-flight briefing and required aviation equipment","Launch and recovery transfers specified by the operator","Roam Ceylon timing and pickup coordination"],"know":["Flights can cancel at short notice because of wind, rain or visibility.","Pregnancy, mobility, age and medical restrictions must be checked with the operator.","Landing location is wind-dependent and may be uneven.","A specific landmark view cannot be promised."],"nearby":["Dambulla Cave Temple","Kandalama Reservoir","Sigiriya","Popham's Arboretum"],"tips":["Keep the following morning flexible in case the flight is postponed or cancelled.","Wear closed shoes and bring a light layer for the pre-dawn wait.","Use a secure camera strap and follow pilot instructions during landing.","Book early within the operating season."],"badges":["Adventure","Sunrise Experience","Photography Spot","Seasonal","Advance Booking Recommended","Roam Ceylon Recommended"],"themes":["adventure","nature"]},
{"slug":"dambulla-trekking-in-jathika-namal-uyana-ironwood-forest-and-rose-quartz-mountain","name":"Jathika Namal Uyana Ironwood Forest & Rose Quartz Walk","category":"Nature","short":"Walk beneath mature na trees and climb onto Jathika Namal Uyana's rose-quartz ridge, where geology, dry-zone ecology and Buddhist history meet.","story":"Jathika Namal Uyana is unusual because several stories occupy the same landscape. A protected ironwood forest creates shade through the dry zone, archaeological remains point to a long Buddhist presence, and the path eventually rises onto a pink quartz formation of great geological significance. The experience is strongest when none of these layers is reduced to a photo stop.\n\nThe quartz section is exposed and can become hot, while forest paths and rock surfaces change after rain. A local guide provides context and helps keep visitors on established routes. The site was recommended for declaration as National Heritage because its environmental, geological and cultural values belong together.","duration":"Approximately 2–3 hours, depending on walking pace and heat","season":"Year-round; begin early and avoid the exposed quartz ridge during severe heat or unsafe weather","highlights":["A mature forest associated with Sri Lanka's national ironwood tree","The transition from shaded dry-zone woodland to exposed rose quartz","Archaeological and Buddhist traces within the forest landscape","Wide views from the higher quartz formation","A rare combination of geology, ecology and cultural history"],"unique":["Forest and mineral landscape are experienced as one protected heritage place","The rose quartz ridge adds geological depth to a Cultural Triangle journey","The walk reveals a quieter form of heritage beyond monumental ruins","Its values are nationally recognised rather than based only on tourism claims"],"included":["Local guide when specified","Site access coordination","Roam Ceylon timing and transport planning","Only entrance fees or refreshments listed in the proposal"],"know":["The quartz ridge is exposed, hot and uneven.","Remain on established paths and never remove quartz, plants or archaeological material.","Footing can become slippery after rain.","Opening and access conditions should be reconfirmed locally."],"nearby":["Dambulla Cave Temple","Sigiriya","Ritigala","Kandalama Reservoir"],"tips":["Start early and carry sufficient drinking water.","Wear closed shoes with reliable grip.","Use sun protection for the exposed upper section.","Treat monastic and archaeological remains quietly and respectfully."],"badges":["Eco Experience","Cultural Heritage","Photography Spot","Roam Ceylon Recommended"],"themes":["nature","heritage"]},
{"slug":"dambulla-climbing-dambulla-cave-temple-5-cave-sanctuaries-housing-150-buddha-stat","name":"Rangiri Dambulla Cave Temple","category":"History","short":"Climb to Dambulla's five sacred cave shrines, where more than two millennia of Buddhist devotion are expressed through sculpture, ritual and painted interiors.","story":"Rangiri Dambulla is a living Buddhist pilgrimage place before it is a collection of artworks. The climb rises above the modern Golden Temple and monumental Buddha at the foot of the hill to five cave shrines shaped under a vast rock overhang. Inside, 157 statues and approximately 2,100 square metres of mural painting create one of South and Southeast Asia's most remarkable sacred interiors.\n\nThe caves were transformed and renewed across centuries of royal patronage; they should not be read as a single frozen moment. A knowledgeable guide helps distinguish the shrines, iconography and later interventions while preserving the quiet expected in active worship. The lower Golden Temple is incorporated into this complete visit rather than sold as a duplicate experience.","duration":"Approximately 1.5–2.5 hours including the climb and lower Golden Temple","season":"Year-round; early morning or later afternoon reduces heat on the exposed climb","highlights":["Five UNESCO-listed cave shrines beneath a single rock overhang","Exceptional Buddhist murals covering walls and ceilings","157 statues arranged through spaces of continuing worship","Views across Dambulla from the upper terrace","The modern Golden Temple and Buddha encountered as the lower part of the visit"],"unique":["The complex has sustained Buddhist pilgrimage and ritual for more than two millennia","Architecture, sculpture and painting work together within natural caves","Successive periods of renewal remain visible rather than belonging to one date","It is a living sacred place, not simply an archaeological monument"],"included":["Roam Ceylon access and timing coordination","Licensed or locally informed interpretation when specified","Lower Golden Temple incorporated into the visit","Entry ticket only when explicitly listed in the proposal"],"know":["Shoulders and knees must be covered and shoes removed before entering sacred areas.","The climb includes exposed steps and uneven rock.","Never pose with your back towards a Buddha image or use flash where prohibited.","Ticket arrangements and opening conditions must be reconfirmed."],"nearby":["Popham's Arboretum","Ibbankatuwa Megalithic Tombs","Kandalama Reservoir","Sigiriya"],"tips":["Visit outside the hottest middle hours.","Carry socks if the stone is likely to be hot after removing shoes.","Keep voices low and allow worshippers space.","Use a guide who can explain artistic layers without rushing the caves."],"badges":["Cultural Heritage","UNESCO Related","Most Popular","Roam Ceylon Recommended"],"themes":["heritage","culture"]},
{"slug":"dambulla-nature-walks-through-pophams-arboretum-dry-zone-flora-and-fauna","name":"Popham's Arboretum Dry-Zone Nature Walk","category":"Nature","short":"Walk through a restored dry-zone woodland at Popham's Arboretum, reading the forest by day or joining a carefully managed nocturnal wildlife experience.","story":"Popham's Arboretum demonstrates what patient ecological restoration can achieve in Sri Lanka's dry zone. Paths move beneath a varied woodland canopy rather than through a formal ornamental garden, allowing attention to settle on bark, leaf, bird call and the relationship between regenerating forest and wildlife.\n\nDay walks suit broad natural-history interpretation. Separate guided night safaris focus particularly on nocturnal species such as the grey slender loris, although sightings are never guaranteed. Roam Ceylon distinguishes these formats clearly and confirms guide, timing and access with the National Institute of Fundamental Studies facility.","duration":"Approximately 1.5–2.5 hours; day walks and night safaris are separate arrangements","season":"Year-round, subject to opening hours and weather; nocturnal walks require advance confirmation","highlights":["A restored dry-zone woodland rather than a conventional landscaped garden","Quiet interpretation of native trees, birds and smaller wildlife","A choice between daylight ecology and a separately guided night walk","Insight into forest regeneration close to Dambulla","Low-impact walking at a pace suited to observation"],"unique":["The arboretum tells a practical story of ecological restoration","Day and night reveal distinctly different forest communities","Its small-scale detail complements the Cultural Triangle's monumental sites","Nocturnal wildlife is approached without guaranteed sightings"],"included":["Confirmed arboretum access","Nature guide where specified","Roam Ceylon timing and transport coordination","Torch or specialist night-walk equipment only when confirmed"],"know":["Night walks require a separate advance arrangement.","Wildlife sightings, including loris or pangolin, cannot be guaranteed.","Use only guide-approved light and never flash nocturnal animals.","Paths may be uneven and weather can affect access."],"nearby":["Dambulla Cave Temple","Kandalama Reservoir","Ibbankatuwa Megalithic Tombs","Sigiriya"],"tips":["Wear muted clothing and closed shoes.","Bring binoculars for a day walk and follow lighting instructions at night.","Use insect repellent without spraying near wildlife.","Move slowly; the value is in details rather than distance covered."],"badges":["Eco Experience","Wildlife","Photography Spot","Advance Booking Recommended"],"themes":["nature","wildlife"]}
]$content$::jsonb) as x(slug text,name text,category text,short text,story text,duration text,season text,highlights jsonb,"unique" jsonb,included jsonb,know jsonb,nearby jsonb,tips jsonb,badges jsonb,themes jsonb);

update public.experiences e set name=x.name,category=x.category,short_description=x.short,full_description=x.story,duration=x.duration,difficulty=null,best_season=x.season,highlights=x.highlights,unique_points=x."unique",included=x.included,things_to_know=x.know,nearby_attractions=x.nearby,traveller_tips=x.tips,badges=x.badges,seo_title=x.name||' | Roam Ceylon',seo_description=x.short,status='published',active=true,updated_at=now() from dambulla_editorial x where e.slug=x.slug;

update public.experiences set status='archived',active=false,updated_at=now() where slug='dambulla-visiting-the-golden-temple-buddha-statue-at-the-foot-of-the-hill';
update public.experiences set status='in_review',active=false,image_review_notes=concat_ws(E'\n',nullif(image_review_notes,''),'Public listing withheld: verify a licensed ATV supplier, authorised route, land permission and insurance before publication.'),updated_at=now() where slug='dambulla-atv-trail-rides-through-rugged-country-paths-and-dry-zone-forests';

delete from public.experience_destinations ed using dambulla_editorial x where ed.experience_id=(select id from public.experiences where slug=x.slug);
insert into public.experience_destinations(experience_id,destination_id) select e.id,d.id from dambulla_editorial x join public.experiences e on e.slug=x.slug join public.destinations d on d.slug='dambulla' on conflict do nothing;
delete from public.experience_themes et using dambulla_editorial x where et.experience_id=(select id from public.experiences where slug=x.slug);
insert into public.experience_themes(experience_id,theme_id) select e.id,t.id from dambulla_editorial x cross join lateral jsonb_array_elements_text(x.themes) m(slug) join public.experiences e on e.slug=x.slug join public.themes t on t.slug=m.slug on conflict do nothing;
insert into public.theme_destinations(theme_id,destination_id) select t.id,d.id from (values('adventure'),('nature'),('heritage'),('culture'),('wildlife')) v(slug) join public.themes t on t.slug=v.slug join public.destinations d on d.slug='dambulla' on conflict do nothing;

do $$ declare c integer; mapped integer; archived integer; held integer; begin select count(*) into c from public.experiences e join dambulla_editorial x on x.slug=e.slug where e.active and e.status='published' and length(e.full_description)>500 and e.duration is not null; select count(*) into mapped from public.experience_destinations ed join public.experiences e on e.id=ed.experience_id join public.destinations d on d.id=ed.destination_id join dambulla_editorial x on x.slug=e.slug where d.slug='dambulla'; select count(*) into archived from public.experiences where slug='dambulla-visiting-the-golden-temple-buddha-statue-at-the-foot-of-the-hill' and status='archived' and not active; select count(*) into held from public.experiences where slug='dambulla-atv-trail-rides-through-rugged-country-paths-and-dry-zone-forests' and status='in_review' and not active; if c<>4 or mapped<>4 or archived<>1 or held<>1 then raise exception 'Dambulla editorial validation failed: published %, mapped %, archived %, held %',c,mapped,archived,held; end if; raise notice 'Dambulla result: 4 bespoke records published and mapped; Golden Buddha duplicate archived; unverified ATV held for review; images preserved.'; end $$;
commit;
